from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
def money_minor(amount):
    if isinstance(amount, bool) or amount is None:
        raise ValueError('invalid amount')
    try:
        number = Decimal(str(amount))
        if not number.is_finite():
            raise ValueError('nonfinite')
        return int((number * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    except (InvalidOperation, TypeError):
        raise ValueError('invalid amount') from None

def shipping_fee(weight_grams):
    if type(weight_grams) is not int or weight_grams < 0:
        raise ValueError('invalid weight')
    return ((weight_grams + 499) // 500) * 150

def reference_key(value):
    if not isinstance(value, str):
        raise ValueError('expected string')
    result = value.strip().casefold()
    if not result:
        raise ValueError('empty reference')
    return result

def retry_delay(attempt):
    if type(attempt) is not int or attempt < 0:
        raise ValueError('invalid attempt')
    return 30 if attempt >= 5 else min(30, 2 ** attempt)

from datetime import datetime, timezone
def utc_stamp(value):
    if not isinstance(value, str) or 'T' not in value:
        raise ValueError('expected timestamp')
    stamp = datetime.fromisoformat(value.replace('Z', '+00:00'))
    if stamp.tzinfo is None:
        stamp = stamp.replace(tzinfo=timezone.utc)
    return stamp.astimezone(timezone.utc).isoformat(timespec='seconds').replace('+00:00', 'Z')

def adjust_stock(stock, sku, delta):
    if not isinstance(stock, dict) or not isinstance(sku, str) or type(delta) is not int:
        raise ValueError('invalid stock update')
    quantity = stock.get(sku, 0) + delta
    if quantity < 0:
        raise ValueError('negative stock')
    result = dict(stock)
    result[sku] = quantity
    return result

from decimal import Decimal, ROUND_HALF_UP
def discounted_minor(price_minor, basis_points):
    if type(price_minor) is not int or type(basis_points) is not int or price_minor < 0 or not 0 <= basis_points <= 10000:
        raise ValueError('invalid discount')
    amount = Decimal(price_minor) * Decimal(10000 - basis_points) / Decimal(10000)
    return int(amount.quantize(Decimal('1'), rounding=ROUND_HALF_UP))

def page_after(ids, after, limit):
    if type(limit) is not int or limit < 0 or not isinstance(ids, list):
        raise ValueError('invalid page')
    if any(not isinstance(x, str) or not x.isascii() or not x.isdigit() for x in ids):
        raise ValueError('expected decimal ids')
    ordered = sorted(dict.fromkeys(ids), key=int)
    if after is not None and after not in ordered:
        raise ValueError('unknown cursor')
    start = 0 if after is None else ordered.index(after) + 1
    return ordered[start:start + limit]

def normalize_sku(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError('invalid sku')
    return value.strip().upper()

def merge_updates(updates):
    if not isinstance(updates, list):
        raise ValueError('expected list')
    versions = {}
    for row in updates:
        if not isinstance(row, dict) or 'version' not in row or 'value' not in row or type(row['version']) is not int or row['version'] < 0:
            raise ValueError('invalid update')
        version = row['version']
        if version in versions and versions[version]['value'] != row['value']:
            raise ValueError('conflicting version')
        versions[version] = row
    return None if not versions else dict(versions[max(versions)])
